// context/TabContext.js
import React, { createContext, useContext, useState, useEffect } from 'react';

const TabContext = createContext();

export const TabProvider = ({ children }) => {
  const [activeTab, setActiveTab] = useState('profile');

  // Синхронизация с URL hash
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      if (hash === 'profile?tab=cart') {
        setActiveTab('cart');
      } else if (hash === 'profile?tab=favorites') {
        setActiveTab('favorites');
      } else if (hash === 'profile?tab=orders') {
        setActiveTab('orders');
      } else if (hash === 'profile') {
        setActiveTab('profile');
      }
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const changeTab = (tab) => {
    setActiveTab(tab);
    if (tab === 'profile') {
      window.location.hash = 'profile';
    } else {
      window.location.hash = `profile?tab=${tab}`;
    }
  };

  return (
    <TabContext.Provider value={{ activeTab, changeTab }}>
      {children}
    </TabContext.Provider>
  );
};

export const useTab = () => {
  const context = useContext(TabContext);
  if (!context) {
    throw new Error('useTab must be used within a TabProvider');
  }
  return context;
};
